    def clamp_step(v):
        return -1 if v < -0.5 else (1 if v > 0.5 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_pair(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            try:
                return [int(x[0]), int(x[1])]
            except Exception:
                return [default[0], default[1]]
        return [default[0], default[1]]

    def safe_list(x):
        return x if isinstance(x, list) else []

    env = observation.get("environment_name", "resource_collection")
    self_pos = safe_pair(observation.get("self_position", [0, 0]))
    opp_pos = safe_pair(observation.get("opponent_position", self_pos))

