        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
        best = corners[0]
        best_score = -1
        for c in corners:
            score = manhattan(c, opp_pos)
            if score > best_score:
                best_score = score
                best = c
        return step_toward(self_pos, best)

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells"))
        if not targets:
            targets = safe_list(observation.get("opponent_territory"))
        if not targets:
            cx = gw // 2
            cy = gh // 2
            return step_toward(self_pos, [cx, cy])

        best = None
        best_score = None
        for t in targets:
            t = safe_pair(t, self_pos)
            score = manhattan(self_pos, t)
            if best is None or score < best_score:
                best = t
                best_score = score
        return step_toward(self_pos, best)

    resources = safe_list(observation.get("resources"))
    if resources:
        best = None
        best_score = None
        for r in resources:
            r = safe_pair(r, self_pos)
            score = manhattan(self_pos, r)
            if best is None or score < best_score:
                best = r
                best_score = score
        return step_toward(self_pos, best)

    # fallback: move toward opponent, but if already adjacent, sidestep toward center if possible
    if manhattan(self_pos, opp_pos) <= 1 and gw > 0 and gh > 0:
        center = [gw // 2, gh // 2]
        return step_toward(self_pos, center)
    return step_toward(self_pos, opp_pos)

